def skill():
    pw, pb = Fraction(1, 3), Fraction(2, 3)
    den = 1 - pb**4 - 4*pw*pb**3
    num = pw * (1 - pb**3)
    v = num / den
    return v.numerator + v.denominator

def standard():
    from itertools import product
    den = num = Fraction(0)
    for seq in product([1, 2], repeat=4):
        pr = Fraction(1)
        cnt = 0
        for s in seq:
            if s == 1:
                pr *= Fraction(1, 3); cnt += 2
            else:
                pr *= Fraction(2, 3); cnt += 1
        if cnt >= 6:
            den += pr
            if seq[0] == 1:
                num += pr
    v = num / den
    return v.numerator + v.denominator

def unique():
    return [standard()]
